    scanf("%d", &n);
    if (n >= 1) {
        f[1] = 1;
    }
    if (n >= 2) {
        f[2] = 2;
    }
    for (i = 3; i <= n; i++) {
        f[i] = f[i - 1] + f[i - 2];
