    for (i = 1; i <= n; i++) {
        if (f[i] % 2 == 0) {
            even++;
        } else {
            odd++;
        }
    }
    printf("方案数 %d\n", f[n]);
    printf("奇数 %d 项\n", odd);
    printf("偶数 %d 项\n", even);
    return 0;
}

