#include <stdio.h>

#define MAXN 25

int main(void)
{
    int n, m, i, j, d, cnt = 0;
    int a[MAXN][MAXN];
    int dr[4] = {-1, 1, 0, 0};
    int dc[4] = {0, 0, -1, 1};
    int resR[MAXN * MAXN], resC[MAXN * MAXN];

    scanf("%d%d", &n, &m);
    for (i = 0; i < n; i++) {
        for (j = 0; j < m; j++) {
            scanf("%d", &a[i][j]);
        }
    }
    for (i = 0; i < n; i++) {
        for (j = 0; j < m; j++) {
            int ok = 1;
            for (d = 0; d < 4; d++) {
                int ni = i + dr[d];
                int nj = j + dc[d];
                if (ni < 0 || ni >= n || nj < 0 || nj >= m) {
                    continue;
                }
                if (a[i][j] <= a[ni][nj]) {
                    ok = 0;
                }
            }
            if (ok) {
                resR[cnt] = i + 1;
                resC[cnt] = j + 1;
                cnt++;
            }
        }
    }
    printf("山峰个数 %d\n", cnt);
    for (i = 0; i < cnt; i++) {
        printf("第 %d 行第 %d 列\n", resR[i], resC[i]);
    }
    return 0;
}

