int main(void)
{
    int n, i, x;
    int first[MAXV], last[MAXV];
    int best = -1, bestVal = -1;

    for (i = 0; i < MAXV; i++) {
        first[i] = -1;
        last[i] = -1;
    }
    scanf("%d", &n);
    for (i = 0; i < n; i++) {
        scanf("%d", &x);
        if (first[x] == -1) {
            first[x] = i;
        }
        last[x] = i;
    }
    for (x = 1; x < MAXV; x++) {
        if (first[x] != -1 && last[x] > first[x]) {
            int d = last[x] - first[x];
            if (d > best) {
                best = d;
                bestVal = x;
            }
        }
    }
    if (bestVal == -1) {
        printf("No repeat\n");
    } else {
        printf("最大跨度 %d\n", best);
        printf("该数值 %d\n", bestVal);
    }
    return 0;
}

