#include <stdio.h>

#define MAXN 25

int main(void)
{
    int n, s, r, c, num = 1;
    int rMin, rMax;
    int a[MAXN][MAXN];

    scanf("%d", &n);
    for (s = 2; s <= 2 * n; s++) {
        rMin = s - n;
        if (rMin < 1) {
            rMin = 1;
        }
        rMax = s - 1;
        if (rMax > n) {
            rMax = n;
        }
        if (s % 2 == 0) {
            for (r = rMin; r <= rMax; r++) {
                c = s - r;
                a[r][c] = num++;
            }
        } else {
            for (r = rMax; r >= rMin; r--) {
                c = s - r;
                a[r][c] = num++;
            }
        }
    }
    for (r = 1; r <= n; r++) {
        for (c = 1; c <= n; c++) {
            if (c > 1) {
                printf(" ");
            }
            printf("%d", a[r][c]);
        }
        printf("\n");
    }
    return 0;
}

