#include <stdio.h>

#define MAXN 100005

int a[MAXN];

int main(void)
{
    int n, i, l, r;
    long long s, cnt = 0;

    scanf("%d%lld", &n, &s);
    for (i = 0; i < n; i++) {
        scanf("%d", &a[i]);
    }
    l = 0;
    r = n - 1;
    while (l < r) {
        long long sum = (long long)a[l] + a[r];
        if (sum == s) {
            if (a[l] == a[r]) {
                long long c = r - l + 1;
                cnt += c * (c - 1) / 2;
                break;
            } else {
                long long vl = a[l], vr = a[r];
                long long cl = 0, cr = 0;
                while (l <= r && a[l] == vl) {
                    l++;
                    cl++;
                }
                while (r >= l && a[r] == vr) {
                    r--;
                    cr++;
                }
                cnt += cl * cr;
            }
        } else if (sum < s) {
            l++;
        } else {
            r--;
        }
    }
    printf("%lld\n", cnt);
    return 0;
}

