#include <stdio.h>

#define MAXN 25

int main(void)
{
    int n, i, j;
    int a[MAXN][MAXN] = {{0}};
    long long dp[MAXN][MAXN] = {{0}};
    int cj;

    scanf("%d", &n);
    for (i = 1; i <= n; i++) {
        for (j = 1; j <= i; j++) {
            scanf("%d", &a[i][j]);
        }
    }
    for (j = 1; j <= n; j++) {
        dp[n][j] = a[n][j];
    }
    for (i = n - 1; i >= 1; i--) {
        for (j = 1; j <= i; j++) {
            long long below = dp[i + 1][j];
            if (dp[i + 1][j + 1] > below) {
                below = dp[i + 1][j + 1];
            }
            dp[i][j] = a[i][j] + below;
        }
    }
    printf("最大和 %lld\n", dp[1][1]);
    printf("路径:");
    cj = 1;
    for (i = 1; i <= n; i++) {
        printf(" %d", a[i][cj]);
        if (i < n && dp[i + 1][cj + 1] > dp[i + 1][cj]) {
            cj++;
        }
    }
    printf("\n");
    return 0;
}
